export function spawnCovenantRailgun(system: VFXSystem, src: Point3D, dst: Point3D, color: string) {
    spawnDeathRay(system, src, dst, '#f59e0b');
}

export function spawnCovenantNuke(system: VFXSystem, pt: Point3D, color: string) {
    // 1. Initial Blinding Flash
    const flash = system.state.getParticle();
    flash.x = pt.x; flash.y = pt.y; flash.z = pt.z + 50;
    flash.life = 0.3; flash.maxLife = 0.3;
    flash.color = '#FFFFFF';
    flash.size = 1000; 
    flash.type = 'BLAST';
    flash.vRotation = 0;
    system.state.particles.push(flash);

    // 2. Base Shockwaves
    spawnShockwave(system, pt.x, pt.y, pt.z, '#FFFFFF', 0.8);
    addImpact(system, pt.x, pt.y, pt.z, color, 'BLAST', 1.0);

    // 3. Mushroom Stem (Rising Column)
    // Dense, fast-rising smoke column
    for(let i=0; i<25; i++) {
        const p = system.state.getParticle();
        const angle = Math.random() * Math.PI * 2;
        const radius = Math.random() * 35;

        p.x = pt.x + Math.cos(angle)*radius;
        p.y = pt.y + Math.sin(angle)*radius;
        p.z = pt.z + 10;

        p.vx = (Math.random()-0.5)*30;
        p.vy = (Math.random()-0.5)*30;
        p.vz = 450 + Math.random() * 300; // High vertical velocity

        p.life = 1.8 + Math.random() * 0.5; p.maxLife = p.life;
        p.color = Math.random() > 0.6 ? '#2a0a0a' : '#450a0a'; // Dark Red/Black Smoke
        p.size = 50 + Math.random() * 40;
        p.type = 'SMOKE'; 
        p.drag = 0.06; // Slow down near top
        p.delay = i * 0.03;
        system.state.particles.push(p);
    }

    // 4. Mushroom Cap (Expanding Cloud Top)
    // Delayed expansion at high altitude
    const capHeight = 350;
    const capDelay = 0.35;

    for(let i=0; i<50; i++) {
        const p = system.state.getParticle();
        const angle = Math.random() * Math.PI * 2;
        const radius = Math.random() * 60;

        p.x = pt.x + Math.cos(angle)*radius;
        p.y = pt.y + Math.sin(angle)*radius;
        p.z = pt.z + capHeight; 

        // Explode outward horizontally
        const speed = 150 + Math.random() * 250;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = (Math.random() - 0.3) * 100; // Slight variation in height

        p.life = 2.5 + Math.random(); p.maxLife = p.life;

        // Fire & Ash mix
        const rng = Math.random();
        if (rng > 0.7) p.color = '#171717'; // Dark Ash
        else if (rng > 0.4) p.color = '#ef4444'; // Red Fire
        else p.color = '#fbbf24'; // Bright Orange Core

        p.size = 90 + Math.random() * 70;
        p.type = 'SMOKE'; 
        p.delay = capDelay + Math.random() * 0.4;
        p.drag = 0.08; // Heavy drag to form rolling cloud
        system.state.particles.push(p);
    }

    // 5. Debris / Fallout
    spawnExplosion(system, pt.x, pt.y, pt.z + 100, 20, '#f97316', 4.0, 1.5, 'DEBRIS');
}

export function spawnCovenantMeteor(system: VFXSystem, pt: Point3D, color: string) {
    setTimeout(() => {
        spawnExplosion(system, pt.x, pt.y, pt.z, 40, '#f97316', 4.0, 1.5, 'DEBRIS'); 
        spawnShockwave(system, pt.x, pt.y, pt.z, '#ea580c', 1.2);
    }, 800);
}

export function spawnCovenantDeathFinger(system: VFXSystem, src: Point3D, dst: Point3D, color: string) {
    spawnDeathRay(system, src, dst, '#dc2626');
}

export function spawnCovenantSoulLink(system: VFXSystem, pt: Point3D, color: string) {
    addImpact(system, pt.x, pt.y, pt.z + 20, '#b45309', 'BLAST', 1.0);

    const count = 8;
    const radius = 350;
    for(let i=0; i<count; i++) {
        const a = (i/count) * Math.PI*2;
        // Target is horizontal perimeter
        const tx = pt.x + Math.cos(a)*radius;
        const ty = pt.y + Math.sin(a)*radius;
        const tz = pt.z + 20; 

        spawnBeam(system, 
            {x: pt.x, y: pt.y, z: pt.z + 20}, 
            {x: tx, y: ty, z: tz}, 
            '#78350f', 2.5, 5
        );
    }
}

