    beam.size = 80; 
    beam.type = 'PILLAR';
    beam.locked = true;
    beam.sortBias = 20;
    system.state.particles.push(beam);

    spawnExplosion(system, pt.x, pt.y, pt.z, 20, '#fff', 5.0, 2.0, 'GLOW');
