// ⚕️ SUPPORT: APOTHECARY BEACON (sb_u2)
export function spawnImperialResurrection(system: VFXSystem, pt: Point3D, color: string) {
    // 1. Central Pillar
    const beam = system.state.getParticle();
    beam.x = pt.x; beam.y = pt.y; beam.z = pt.z;
    beam.life = 2.5; beam.maxLife = 2.5;
    beam.color = '#86efac'; 
    beam.size = 60; 
    beam.type = 'PILLAR'; 
    beam.locked = true;
    beam.sortBias = 20;
    system.state.particles.push(beam);

    // 2. Ascending Souls (Spiral)
    const count = 20;
    for(let i=0; i<count; i++) {
        const p = system.state.getParticle();
        const angle = (i / count) * Math.PI * 2;
        const radius = 60;

        p.x = pt.x + Math.cos(angle) * radius;
        p.y = pt.y + Math.sin(angle) * radius;
        p.z = pt.z;

        // Simulating spiral by giving tangent velocity
        p.vx = -Math.sin(angle) * 100;
        p.vy = Math.cos(angle) * 100;
        p.vz = 200 + Math.random() * 50; // Rise up

        p.life = 2.0; p.maxLife = 2.0;
        p.color = '#ffffff';
        p.size = 5 + Math.random() * 4;
        p.type = 'GLOW';
        p.drag = 0; 
        p.delay = i * 0.1; // Sequential rise
        system.state.particles.push(p);
