import { SceneTheme } from "../../types";
import { HEX_SIZE } from "../../constants";
import { AssetManager } from "../assets";
import { MapConfig } from "../utils";
import { createCanvas } from "../graphics/CanvasUtils";

export class BackgroundRenderer {
    private staticCache: HTMLCanvasElement | null = null;
    private lastSceneId: string = "";
    private lastWidth: number = 0;
    private lastHeight: number = 0;

    public draw(
        ctx: CanvasRenderingContext2D, 
        width: number, 
        height: number, 
        scene: SceneTheme, 
        mapConfig: MapConfig, 
        globalTime: number
    ): void {
        // 1. Check if we need to regenerate static cache
        if (!this.staticCache || this.lastSceneId !== scene.id || this.lastWidth !== width || this.lastHeight !== height) {
            this.updateStaticCache(width, height, scene);
        }

        // 2. Draw Static Layer (Instant blit)
        if (this.staticCache) {
            ctx.drawImage(this.staticCache, 0, 0);
        }

        // 3. Dynamic Elements (Clouds / Fog / God Rays)
        // These need to animate every frame
        this.drawDynamicElements(ctx, width, height, scene, mapConfig, globalTime);
    }

    private updateStaticCache(w: number, h: number, scene: SceneTheme) {
        // Create or Resize Canvas
        if (!this.staticCache) {
            const { canvas } = createCanvas(w, h);
            this.staticCache = canvas;
        } else {
            this.staticCache.width = w;
            this.staticCache.height = h;
        }

        this.lastSceneId = scene.id;
        this.lastWidth = w;
        this.lastHeight = h;

        const ctx = this.staticCache.getContext('2d')!;
        ctx.clearRect(0, 0, w, h);

        // --- DRAW STATIC CONTENT ---

        // 1. Base Gradient
        const bgGrad = ctx.createLinearGradient(0, 0, 0, h);
        bgGrad.addColorStop(0, scene.background);
        bgGrad.addColorStop(0.5, scene.horizon);
        bgGrad.addColorStop(1, '#020617');
        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, w, h);

        // 2. Horizon Glow (Static)
        const hY = h * 0.6;
        const hGlow = ctx.createRadialGradient(w/2, hY, w*0.1, w/2, hY, w*0.8);
        hGlow.addColorStop(0, scene.horizon);
        hGlow.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.4;
        ctx.fillStyle = hGlow;
        ctx.fillRect(0, 0, w, h);
        ctx.globalCompositeOperation = 'source-over';
        ctx.globalAlpha = 1.0;

        // 3. Static Stars / Nebula Base
        if (scene.id === 'VOID' || scene.id === 'ICE' || scene.id === 'FOREST') {
             ctx.fillStyle = '#fff';
             const seed = 123; 
             for(let i=0; i<80; i++) {
                 const sx = (Math.sin(i * seed) * 0.5 + 0.5) * w;
                 const sy = (Math.cos(i * seed * 1.5) * 0.5 + 0.5) * h * 0.8;
                 const size = Math.random() * 2;
                 // Static Alpha for base stars
                 ctx.globalAlpha = 0.6 * (scene.id === 'VOID' ? 0.8 : 0.4);
                 ctx.beginPath(); ctx.arc(sx, sy, size, 0, Math.PI*2); ctx.fill();
             }
        }

        // 4. Distant Silhouette (Static Mountains)
        if (scene.id === 'FOREST' || scene.id === 'ICE' || scene.id === 'DESERT' || scene.id === 'MAGMA') {
            ctx.globalCompositeOperation = 'source-over';
            const drawMountainLayer = (yOffset: number, color: string, roughness: number, seedOffset: number) => {
                ctx.fillStyle = color;
                ctx.beginPath();
                ctx.moveTo(0, h);
                for(let x=0; x<=w; x+=20) {
                    // Use static seed instead of time
                    const n = Math.sin(x * 0.01 + seedOffset) * Math.cos(x * 0.03) * roughness;
                    ctx.lineTo(x, h * 0.55 + yOffset + n);
                }
                ctx.lineTo(w, h);
                ctx.fill();
            };
            ctx.globalAlpha = 0.3;
            drawMountainLayer(0, scene.fogColor, 60, 0);
            ctx.globalAlpha = 0.5;
            drawMountainLayer(60, scene.horizon, 40, 100);
        }
    }

    private drawDynamicElements(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme, mapConfig: MapConfig, t: number) {
        ctx.save();

        // 1. Moving Clouds
        if (scene.id !== 'VOID') {
            this.drawMovingClouds(ctx, w, h, scene, t);
        }

        // 2. Twinkling Stars / Moving Nebula (Overlay)
        if (scene.id === 'VOID' || scene.id === 'ICE') {
             ctx.globalCompositeOperation = 'screen';
             const cloudCount = 3;
             for(let i=0; i<cloudCount; i++) {
                 const x = (Math.sin(i * 1.5 + t * 0.05) * 0.5 + 0.5) * w;
                 const y = (Math.cos(i * 1.2 + t * 0.03) * 0.3 + 0.3) * h;
                 const radius = w * 0.4;
                 const grad = ctx.createRadialGradient(x, y, 0, x, y, radius);
                 grad.addColorStop(0, scene.ambientColor);
                 grad.addColorStop(1, 'transparent');
                 ctx.fillStyle = grad;
                 ctx.globalAlpha = 0.1; // Subtler
                 ctx.beginPath(); ctx.arc(x, y, radius, 0, Math.PI*2); ctx.fill();
             }
        }

        // 3. God Rays & Sky Features
        this.drawGodRays(ctx, w, h, t);
        this.drawSkyFeatures(ctx, w, h, scene, t);

        // 4. Atmospheric Fog (Screen Space)
        const mapPxW = mapConfig.w * HEX_SIZE * 2;
        const mapPxH = mapConfig.h * HEX_SIZE * 2;
        this.drawAtmosphericFog(ctx, mapPxW, mapPxH, scene, t);

        // 5. Vignette (Cheaper)
        // Only draw if strictly needed, or bake into static. 
        // Keeping here for now as it helps focus dynamic elements.
        const rad = Math.min(w, h) * 0.8;
        const vig = ctx.createRadialGradient(w/2, h/2, rad * 0.5, w/2, h/2, rad * 1.5);
        vig.addColorStop(0, 'transparent');
        vig.addColorStop(1, 'rgba(0,0,0,0.5)');
        ctx.globalCompositeOperation = 'source-over';
        ctx.globalAlpha = 1.0;
        ctx.fillStyle = vig;
        ctx.fillRect(0, 0, w, h);

        ctx.restore();
    }

    private drawMovingClouds(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme, t: number) {
        const layers = 2;
        ctx.globalCompositeOperation = 'soft-light';
        ctx.fillStyle = scene.fogColor;

        for(let l=0; l<layers; l++) {
            const speed = (l + 1) * 10;
            const yBase = h * (0.1 + l * 0.2);
            const scale = 100 + l * 50;

            ctx.globalAlpha = 0.1 + l * 0.1;

            for(let i=0; i<6; i++) {
                const x = ((t * speed + i * (w/4)) % (w + scale*2)) - scale;
                const y = yBase + Math.sin(t * 0.5 + i) * 20;

                // Use rect for clouds if distant to save path perf, or ellipse
                ctx.beginPath();
                ctx.ellipse(x, y, scale, scale * 0.4, 0, 0, Math.PI*2);
                ctx.fill();
            }
        }
    }

    private drawGodRays(ctx: CanvasRenderingContext2D, w: number, h: number, t: number) {
        ctx.save();
        ctx.globalCompositeOperation = 'overlay';

        const sourceX = w * 0.8 + Math.sin(t * 0.1) * 100;
        const sourceY = -100;

        const grad = ctx.createRadialGradient(sourceX, sourceY, 50, sourceX, sourceY, w);
        grad.addColorStop(0, 'rgba(255, 255, 255, 0.15)'); 
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;

        // Reduced ray count for perf
        for(let i=0; i<4; i++) {
            const angle = Math.PI / 2 + 0.3 + Math.sin(t * 0.05 + i) * 0.1 + (i * 0.15);
            const width = Math.PI / 32 * (1 + Math.sin(t + i)*0.2);
            const rayLen = w * 1.5;

            ctx.beginPath();
            ctx.moveTo(sourceX, sourceY);
            ctx.lineTo(sourceX + Math.cos(angle - width) * rayLen, sourceY + Math.sin(angle - width) * rayLen);
            ctx.lineTo(sourceX + Math.cos(angle + width) * rayLen, sourceY + Math.sin(angle + width) * rayLen);
            ctx.fill();
        }
        ctx.restore();
    }

    private drawSkyFeatures(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme, t: number) {
        if (scene.bgFeature === 'NONE') return;

        ctx.globalCompositeOperation = 'screen';

        if (scene.bgFeature === 'SKY_RIVER') {
            const color = scene.ambientColor;
            // Reduced loop count
            for(let i=0; i<3; i++) {
                const lineWidth = 30 + i * 10;
                const amplitude = 30 + i * 10;
                const phase = t * (0.2 + i * 0.05);
                const yBase = h * 0.3 + i * 20;

                ctx.strokeStyle = color;
                ctx.lineWidth = lineWidth;
                ctx.globalAlpha = 0.1 - (i * 0.01);
                ctx.beginPath();
                // Increased step size
                for(let x=0; x<=w; x+=30) {
                    const y = yBase + Math.sin(x * 0.005 + phase) * amplitude + Math.cos(x * 0.01 - t*0.5) * 20;
                    if (x===0) ctx.moveTo(x, y);
                    else ctx.lineTo(x, y);
                }
                ctx.stroke();
            }
        } else if (scene.bgFeature === 'AURORA') {
            const colors = ['#34d399', '#818cf8']; 
            for(let i=0; i<2; i++) {
                const grad = ctx.createLinearGradient(0, 0, 0, h);
                grad.addColorStop(0, 'transparent');
                grad.addColorStop(0.2, colors[i]);
                grad.addColorStop(0.8, 'transparent');

                ctx.fillStyle = grad;
                ctx.globalAlpha = 0.15;
                const phase = t * 0.5 + i * 2;
                ctx.beginPath();
                ctx.moveTo(0, h);
                for(let x=0; x<=w; x+=40) {
                    const y = h * 0.4 + Math.sin(x * 0.01 + phase) * 100 * Math.sin(x*0.002);
                    ctx.lineTo(x, y);
                }
                ctx.lineTo(w, 0); 
                ctx.lineTo(0, 0); 
                ctx.fill();
            }
        } else if (scene.bgFeature === 'HEAT_WAVE') {
            ctx.fillStyle = '#fca5a5';
            ctx.globalAlpha = 0.05;
            // Reduced count
            for(let i=0; i<5; i++) {
                const x = (i / 5) * w;
                const height = h * 0.5 + Math.sin(t * 2 + i) * 50;
                const width = w / 5;
                ctx.fillRect(x, h - height, width, height);
            }
        }
    }

    private drawAtmosphericFog(ctx: CanvasRenderingContext2D, mapW: number, mapH: number, scene: SceneTheme, t: number) {
        ctx.save();
        ctx.globalCompositeOperation = 'screen';

        const fogColor = scene.fogColor || '#fff';
        const fogSprite = AssetManager.getFogCloud(fogColor); 
        const numClouds = 6; // Reduced from 8

        for (let i = 0; i < numClouds; i++) {
            const speed = 20;
            const x = ((t * speed + i * (mapW / numClouds)) % (mapW * 1.5)) - mapW * 0.25;
            const y = (Math.sin(i * 123 + t * 0.1) * 0.5 + 0.5) * mapH;
            const size = 300 + Math.sin(i) * 100;

            ctx.globalAlpha = 0.1 + Math.sin(t * 0.5 + i) * 0.05; 
            ctx.drawImage(fogSprite, x - size/2, y - size/2, size, size * 0.6);
        }
        ctx.restore();
    }
}

import { Particle } from "../state";
import { isChaosStyle } from "../utils";
import { ISO_SCALE_Y } from "../../../../constants";
import { SurfaceAssets } from "../../../graphics/SurfaceAssets";
import { VFXFactory } from "../../../graphics/VFXFactory";

const UNIT_CHEST_HEIGHT = 40;

// Optimization: Precomputed Unit Hexagon (Radius 1.0)
const HEX_CORNERS_X = [1, 0.5, -0.5, -1, -0.5, 0.5];
const HEX_CORNERS_Y = [0, 0.866, 0.866, 0, -0.866, -0.866];

function traceHexagonFast(ctx: CanvasRenderingContext2D, r: number) {
    ctx.beginPath();
    ctx.moveTo(HEX_CORNERS_X[0] * r, HEX_CORNERS_Y[0] * r);
    for (let i = 1; i < 6; i++) {
        ctx.lineTo(HEX_CORNERS_X[i] * r, HEX_CORNERS_Y[i] * r);
    }
    ctx.closePath();
}

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // 1. Base Position (Int Snapping for Speed)
        ctx.translate(Math.floor(p.x), Math.floor(p.y));

        const now = Date.now() / 1000;

        // 2. Texture Resolution
        if (!p.texture && !p.image && !['PILLAR', 'DOMAIN', 'HEX_BEAM', 'GIANT_HEX', 'GRID_FIELD', 'DEATH_RAY', 'BEAM'].includes(p.type)) {
            if (p.type === 'GLOW' || p.type === 'SPARK' || p.type === 'HEX_GLOW') p.texture = VFXFactory.getTexture('GLOW', p.color);
            else if (p.type === 'SMOKE') p.texture = VFXFactory.getTexture('NOISE', p.color);
            else if (p.type === 'BLAST') p.texture = VFXFactory.getTexture('BLAST', p.color);
            else if (p.type === 'DEBRIS' || p.type === 'ROCK') p.texture = VFXFactory.getTexture('SOLID', p.color);
            else if (p.type === 'HEX_LOCK' || p.type === 'SHOCKWAVE') p.texture = VFXFactory.getTexture('OUTLINE', p.color);

            // New Pre-baked types for performance
            else if (p.type === 'SHARD') p.texture = VFXFactory.getTexture('SHARD', p.color);
            else if (p.type === 'CHIP') p.texture = VFXFactory.getTexture('CHIP', p.color);
        }

        // 3. Render Logic
        if (p.image) {
            ctx.rotate(p.rotation);
            ctx.globalAlpha = 1 - progress;
            const size = Math.floor(p.size);
            ctx.drawImage(p.image, -size/2, -size/2, size, size);
        }
        else if (p.texture) {
            if (p.type === 'SMOKE' || p.type === 'GLOW' || p.type === 'HEX_GLOW') {
                ctx.globalCompositeOperation = 'screen';
                ctx.globalAlpha = (1 - progress);
                const scale = p.type === 'SMOKE' ? (1 + progress) : (1 - progress * 0.5);
                ctx.scale(scale, scale);
                ctx.rotate(p.rotation);
                const s2 = p.size * 2;
                ctx.drawImage(p.texture, -p.size, -p.size, s2, s2);
            } 
            else if (p.type === 'SPARK') {
                ctx.globalCompositeOperation = 'lighter';
                ctx.rotate(Math.atan2(p.vy, p.vx));
                ctx.scale(Math.min(3, 1 + p.size/10), 0.5);
                ctx.globalAlpha = 1 - progress;
                const s2 = p.size * 2;
                ctx.drawImage(p.texture, -p.size, -p.size, s2, s2);
            }
            else {
                ctx.rotate(p.rotation);
                const s2 = p.size * 2;
                // Standard texture draw
                ctx.drawImage(p.texture, -p.size, -p.size, s2, s2);
            }
        }
        else {
            this.drawProcedural(ctx, p, progress, isChaos, now);
        }

        ctx.restore();
    },

    drawProcedural(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean, now: number) {
        // Optimized: Removed simple CHIP/SHARD drawing as they are now textured

        if (p.type === 'HEX_BEAM') {
            ctx.scale(1, ISO_SCALE_Y);
            ctx.globalCompositeOperation = 'lighter';
            ctx.fillStyle = p.color;
            ctx.globalAlpha = (1 - progress) * 0.9;
            traceHexagonFast(ctx, p.size); ctx.fill();
            ctx.fillStyle = '#fff';
            traceHexagonFast(ctx, p.size * 0.6); ctx.fill();
        }
        else if (p.type === 'GRID_FIELD') {
            if (p.color === '#be123c' || p.color.includes('blood')) {
                SurfaceAssets.drawLiquidSurface(ctx, 0, 0, '#991b1b', now, progress);
            } else {
                const height = 15 * progress;
                SurfaceAssets.drawExtrudedHex(ctx, 0, 0, height, p.color, 0.6, false);
            }
        }
        else if (p.type === 'PILLAR') {
            const h = 1200; 
            const width = p.size * (1 - progress * 0.5);

            ctx.save();
            ctx.globalCompositeOperation = 'screen';

            const grad = ctx.createLinearGradient(0, 0, 0, -h);
            grad.addColorStop(0, p.color);
            grad.addColorStop(0.2, '#fff');
            grad.addColorStop(1, 'rgba(0,0,0,0)');

            ctx.fillStyle = grad;
            ctx.globalAlpha = (1 - progress);
            ctx.fillRect(-width/2, -h, width, h);

            ctx.scale(1, ISO_SCALE_Y);
            ctx.beginPath(); ctx.arc(0, 0, width, 0, Math.PI*2);
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 3;
            ctx.stroke();

            ctx.restore();
        }
        else if (p.type === 'DOMAIN') {
            ctx.save();
            ctx.scale(1, ISO_SCALE_Y);
            const r = p.size * (progress < 0.1 ? progress/0.1 : 1.0); 

            ctx.globalCompositeOperation = 'lighter';
            const grad = ctx.createRadialGradient(0, 0, r*0.5, 0, 0, r);
            grad.addColorStop(0, 'rgba(0,0,0,0)');
            grad.addColorStop(0.8, p.color);
            grad.addColorStop(1, 'rgba(255,255,255,0.5)');

            ctx.fillStyle = grad;
            ctx.globalAlpha = 0.3 * (1 - progress);
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

            ctx.strokeStyle = '#ffffff';
            ctx.globalAlpha = 0.15;
            ctx.lineWidth = 1;
            ctx.setLineDash([10, 10]);
            ctx.beginPath(); ctx.arc(0, 0, r * 0.9, 0, Math.PI*2); ctx.stroke();

            ctx.restore();
        }
        else if (p.type === 'BEAM' || p.type === 'DEATH_RAY') {
            // Optimized Beam drawing
            if (p.sx !== undefined && p.sy !== undefined && p.sz !== undefined &&
                p.tx !== undefined && p.ty !== undefined && p.tz !== undefined) {

                const dx = p.tx - p.sx; 
                const startVisY = -UNIT_CHEST_HEIGHT;

                const worldYDelta = p.ty - p.sy;
                const zDelta = p.tz - p.sz;
                const targetVisY = worldYDelta - zDelta - UNIT_CHEST_HEIGHT;

                const dist = Math.sqrt(dx*dx + (targetVisY - startVisY)**2);
                const angle = Math.atan2(targetVisY - startVisY, dx);

                ctx.save();
                ctx.translate(0, startVisY); 
                ctx.rotate(angle);

                if (p.type === 'BEAM') {
                    const coreWidth = p.size * Math.sin((1-progress) * Math.PI);
                    if (coreWidth > 0.5) {
                        ctx.lineCap = 'round';
                        ctx.globalCompositeOperation = 'screen';

                        ctx.strokeStyle = p.color;
                        ctx.globalAlpha = 0.3 * (1 - progress);
                        ctx.lineWidth = coreWidth * 6;
                        ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();

                        ctx.globalCompositeOperation = 'lighter';
                        ctx.globalAlpha = 0.8 * (1 - progress);
                        ctx.lineWidth = Math.max(1, coreWidth * 0.8);

                        // Optimized Helix: Less segments
                        const freq = 0.1; const amp = Math.max(3, coreWidth * 2);
                        const speed = now * 20; const step = 10; // Increased step size

                        ctx.beginPath();
                        for (let i = 0; i <= dist; i += step) {
                            const yOffset = Math.sin(i * freq - speed) * amp;
                            if (i===0) ctx.moveTo(i, yOffset); else ctx.lineTo(i, yOffset);
                        }
                        ctx.stroke();

                        ctx.strokeStyle = '#fff';
                        ctx.lineWidth = Math.max(1, coreWidth);
                        ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();
                    }
                } else {
                    const width = p.size * (1 - progress);
                    if (width > 0.5) {
                        ctx.globalCompositeOperation = 'source-over';
                        ctx.strokeStyle = '#000';
                        ctx.lineWidth = width * 1.5;
                        ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();

                        ctx.globalCompositeOperation = 'lighter';
                        ctx.strokeStyle = p.color;
                        ctx.shadowColor = p.color;
                        ctx.shadowBlur = 10; // Reduced blur
                        ctx.lineWidth = Math.max(1, width * 0.6);
                        ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();

                        ctx.strokeStyle = '#fff';
                        ctx.lineWidth = Math.max(1, width * 0.2);
                        ctx.shadowBlur = 0; // Remove blur for inner core
                        ctx.stroke();
                    }
                }
                ctx.restore();
            }
        }
        else if (p.type === 'GIANT_HEX') {
            ctx.scale(1, ISO_SCALE_Y);
            ctx.rotate(p.rotation);
            ctx.fillStyle = p.color;
            ctx.globalAlpha = 0.8;
            traceHexagonFast(ctx, p.size); ctx.fill();
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            traceHexagonFast(ctx, p.size); ctx.stroke();
        }
    }
};

import { createCanvas } from "./CanvasUtils";
import { isChaosStyle } from "../systems/vfx/utils";

// Dimensions
const TEXTURE_SIZE = 128; 
const CENTER = TEXTURE_SIZE / 2;

class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public getTexture(type: 'GLOW' | 'SOLID' | 'OUTLINE' | 'NOISE' | 'BLAST' | 'SHARD' | 'CHIP', color: string): HTMLCanvasElement {
        const key = `${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const texture = this.bakeTexture(type, color);
        this.cache.set(key, texture);
        return texture;
    }

    private bakeTexture(type: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        const r = CENTER - 4;

        ctx.translate(CENTER, CENTER);

        if (type === 'GLOW') {
            const grad = ctx.createRadialGradient(0, 0, r * 0.2, 0, 0, r);
            grad.addColorStop(0, '#ffffff');
            grad.addColorStop(0.2, color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            this.pathHex(ctx, r);
            ctx.fill();
        } 
        else if (type === 'SOLID') {
            ctx.fillStyle = color;
            this.pathHex(ctx, r * 0.9);
            ctx.fill();
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 2;
            this.pathHex(ctx, r * 0.9);
            ctx.stroke();
        }
        else if (type === 'OUTLINE') {
            ctx.strokeStyle = color;
            ctx.lineWidth = 4;
            ctx.shadowColor = color;
            ctx.shadowBlur = 10;
            this.pathHex(ctx, r * 0.8);
            ctx.stroke();
        }
        else if (type === 'NOISE') {
            ctx.fillStyle = color;
            this.pathHex(ctx, r);
            ctx.fill();
            ctx.globalCompositeOperation = 'overlay';
            ctx.fillStyle = 'rgba(0,0,0,0.3)';
            for(let i=0; i<20; i++) {
                const rx = (Math.random() - 0.5) * r * 1.5;
                const ry = (Math.random() - 0.5) * r * 1.5;
                const rs = Math.random() * r * 0.4;
                ctx.beginPath(); ctx.arc(rx, ry, rs, 0, Math.PI*2); ctx.fill();
            }
        }
        else if (type === 'BLAST') {
            const isChaos = isChaosStyle(color);
            if (isChaos) {
                ctx.fillStyle = color;
                ctx.beginPath();
                for(let i=0; i<12; i++) {
                    const angle = (i / 12) * Math.PI * 2;
                    const rad = (i % 2 === 0) ? r : r * 0.4;
                    const x = Math.cos(angle) * rad;
                    const y = Math.sin(angle) * rad;
                    if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
                }
                ctx.closePath();
                ctx.fill();
            } else {
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
                grad.addColorStop(0, '#ffffff');        
                grad.addColorStop(0.3, color);          
                grad.addColorStop(1, 'transparent');  
                ctx.fillStyle = grad;
                ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();
            }
        }
        else if (type === 'CHIP') {
            // Simple Square Chip
            ctx.fillStyle = color;
            ctx.fillRect(-r/2, -r/2, r, r);
        }
        else if (type === 'SHARD') {
            // Triangular Shard
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(r, 0);
            ctx.lineTo(-r * 0.5, r * 0.4);
            ctx.lineTo(-r * 0.5, -r * 0.4);
            ctx.fill();
            // Subtle highlight
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 4;
            ctx.stroke();
        }

        return canvas;
    }

    private pathHex(ctx: CanvasRenderingContext2D, r: number) {
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const angle = i * Math.PI / 3;
            const x = Math.cos(angle) * r;
            const y = Math.sin(angle) * r;
            if (i === 0) ctx.moveTo(x, y);
            else ctx.lineTo(x, y);
        }
        ctx.closePath();
    }

    generateGlowOrb(color: string, size: number = 64): HTMLCanvasElement {
        return this.getTexture('GLOW', color);
    }

    generateFogCloud(color: string): HTMLCanvasElement {
        return this.getTexture('GLOW', color); 
    }

    generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        return this.createLegacyProjectile(visual, color);
    }

    generateBlastZone(color: string): HTMLCanvasElement {
        return this.getTexture('BLAST', color);
    }

    private createLegacyProjectile(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(96, 64);
        const cx = 48, cy = 32;
        ctx.shadowColor = color; ctx.shadowBlur = 10;
        ctx.lineCap = 'round'; ctx.lineJoin = 'round';

        if (visual === 'ARROW') {
            ctx.strokeStyle = '#fff'; ctx.lineWidth = 2;
            ctx.beginPath(); ctx.moveTo(10, cy); ctx.lineTo(80, cy); ctx.stroke();
            ctx.fillStyle = color;
            ctx.beginPath(); ctx.moveTo(90, cy); ctx.lineTo(70, cy - 8); ctx.lineTo(75, cy); ctx.lineTo(70, cy + 8); ctx.fill();
        } else {
            const grad = ctx.createLinearGradient(0, 0, 96, 0);
            grad.addColorStop(0, 'transparent'); grad.addColorStop(0.5, color); grad.addColorStop(1, '#fff');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.ellipse(cx, cy, 30, 8, 0, 0, Math.PI*2); ctx.fill();
        }
        return canvas;
    }
}

